#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "create_runtime_float_log.h"
#include "create_runtime_float_curveinfo.h"
#include "initialize_float_layer_keys.h"
#include "write_float_log_curveinfo.h"
#include "graph_float_curve_sampler.h"
#include "clip_hierarchy.h"
#include "channel_binding.h"
#include "session_expression_runtime.h"
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)return 1;SessionRuntime r(loadGraph(argv[1]));MutationCoordinator m;RuntimeFloatLayerState state(r);std::array<char,16>a{},b{},c{};a.fill(0x61);b.fill(0x62);c.fill(0x63);auto start=static_cast<uint32_t>(r.graph.elements.size());auto log=createRuntimeFloatLog(r,m,a,b,4,&state);auto layer=r.elements.graphHandles.at(start+1);initializeEmptyFloatLayerKeys(r,layer,{{0,0.f},{10000,1.f},{30000,3.f},{70000,7.f}});auto target=createRuntimeFloatCurveInfo(r,m,c,"sampling info",4);auto max=r.attributes.resolve(r.graph,r.elements,r.attributes.find(target,"maxvalue"));setWireU32(max->values[0],0x41200000);writeFloatLogCurveInfo(r,m,state,log,target,false,[](){return false;});auto s=bindGraphFloatCurveSampler(r.graph,start,start+1);if(s.sample(20000)!=2)throw std::runtime_error("bound sample failed");uint32_t channel=0xffffffff;for(uint32_t i=0;i<start;++i)if(r.graph.strings.at(r.graph.elements[i].type)=="DmeChannel"){ChannelBinding candidate(r.graph,i);if(candidate.destination.present()&&candidate.destination.scalarType==3){channel=i;break;}}if(channel==0xffffffff)throw std::runtime_error("no float destination channel");auto channelLog=runtimeAttribute(r.graph,channel,"log");channelLog->values[0].reference=start;auto mode=runtimeAttribute(r.graph,channel,"mode");setWireU32(mode->values[0],3);ChannelBinding binding(r.graph,channel);SessionAttributeChanges changes;if(!executeSessionFloatPlay(r.graph,binding,20000,&changes)||wireFloat(runtimeAttribute(r.graph,binding.destination.element,binding.destination.attribute)->values.at(binding.destination.index))!=2)throw std::runtime_error("curve channel write failed");auto verifyModes=[&](Graph&g,const ChannelBinding&bound){
 const std::array<double,16>expected{2,2,1+2*std::sqrt(.5),1+2*(1-std::sqrt(.5)),2,99.0/48,2,2,1.91145,2.08855,2,1.8125,2,1.875,1+2*(1-std::sqrt(double(.001f))),1};
 auto*curves=runtimeAttribute(g,start+1,"curvetypes");for(uint32_t code=0;code<16;++code){for(auto&value:curves->values)setWireU32(value,(code<<8)|code);if(!executeSessionFloatPlay(g,bound,20000))throw std::runtime_error("mode channel rejected");float actual=wireFloat(runtimeAttribute(g,bound.destination.element,bound.destination.attribute)->values.at(bound.destination.index));if(std::abs(actual-expected[code])>3e-6)throw std::runtime_error("mode channel value mismatch code="+std::to_string(code)+" actual="+std::to_string(actual));}
 for(auto&value:curves->values)setWireU32(value,0);
 };verifyModes(r.graph,binding);saveGraph(r.graph,argv[2]);auto reload=loadGraph(argv[2]);auto restored=bindGraphFloatCurveSampler(reload,start,start+1);if(restored.sample(20000)!=2||restored.sample(80000)!=7)throw std::runtime_error("restored sample failed");ChannelBinding replay(reload,channel);if(!executeSessionFloatPlay(reload,replay,30000)||wireFloat(runtimeAttribute(reload,replay.destination.element,replay.destination.attribute)->values.at(replay.destination.index))!=3)throw std::runtime_error("restored curve channel write failed");verifyModes(reload,replay);std::cout<<"all_curve_codes=16 channel_mode_checks=32 graph_curve_binding=verified save_reload=verified channel_writes=2\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

